root<-normalizePath('260925_Re',winslash='/');src<-file.path(root,'data/processed/real_count_deconvolution_20260926_142741')
out<-file.path(root,'runs',paste0('real_count_bayesprism_',format(Sys.time(),'%Y%m%d_%H%M%S')));dir.create(out,recursive=TRUE)
con<-file(file.path(out,'run.log'),'wt');sink(con,split=TRUE);sink(con,type='message')
suppressPackageStartupMessages({library(BayesPrism);library(Matrix)})
ref<-as.matrix(readMM(file.path(src,'reference_counts_cells_by_genes.mtx')));lab<-read.csv(file.path(src,'reference_cell_labels.csv'));genes<-read.csv(file.path(src,'gene_ids.csv'));rownames(ref)<-lab$cell_id;colnames(ref)<-genes$gene_id
mix<-as.matrix(read.csv(file.path(src,'mixture_counts.csv'),row.names=1,check.names=FALSE));stopifnot(all(mix>=0),all(mix==round(mix)))
prism<-new.prism(reference=ref,input.type='count.matrix',cell.type.labels=lab$compartment,cell.state.labels=lab$compartment,key='malignant_epithelial',mixture=mix,outlier.cut=1,outlier.fraction=1)
writeLines(c('DepMap Public 26Q1 integer read counts; same counts, genes, reference cells as paired NNLS input.','BayesPrism 2.2.3, fixed reference initial Gibbs; NO joint cross-sample reference update and NO cohort-dependent gene filtering.','chain.length=1000; burn.in=500; thinning=2; seed=7; n.cores=2.','No true cell-line compartment ground truth is assumed. Bulk/scRNA platforms differ.'),file.path(out,'CONFIG.txt'));saveRDS(prism,file.path(out,'prism_input.rds'))
bp<-run.prism(prism,n.cores=2,update.gibbs=FALSE,gibbs.control=list(chain.length=1000,burn.in=500,thinning=2,seed=7));saveRDS(bp,file.path(out,'BayesPrism.rds'))
theta<-get.fraction(bp,which.theta='first',state.or.type='state');stopifnot(all(is.finite(theta)),max(abs(rowSums(theta)-1))<1e-6);write.csv(theta,file.path(out,'fractions.csv'));write.csv(bp@posterior.initial.cellState@theta.cv,file.path(out,'fractions_posterior_cv.csv'))
for(k in colnames(theta))write.csv(get.exp(bp,state.or.type='state',cell.name=k),gzfile(file.path(out,paste0('Z_',k,'.csv.gz'))))
writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt'));writeLines('real_count_fixed_reference_BayesPrism_complete',file.path(out,'COMPLETE.txt'));sink(type='message');sink();close(con);cat(out,'\n')
